en = json.load(open('src/i18n/locales/en.json'))
ph = lambda s: sorted(re.findall(r'\{\w+\}', s))
for lang, vals in L.items():
    assert len(vals) == len(KEYS), (lang, len(vals), len(KEYS))
    d = {}
    for k, v in zip(KEYS, vals):
        assert ph(v) == ph(en[k]), (lang, k, v, en[k])  # placeholders must match English
        d[k] = v
    for l2 in ('en','pt','es','fr','ar','hi','zh'):  # language names are the same in every locale
        d[f'lang.{l2}'] = en[f'lang.{l2}']
    json.dump(dict(sorted(d.items())), open(f'src/i18n/locales/{lang}.json', 'w'), ensure_ascii=False, indent=2)
    open(f'src/i18n/locales/{lang}.json', 'a').write('\n')
    print(lang, len(d), 'keys')
